/*
 * Project      : APB-CSR-Generator
 * Author       : Nguyen Quan (user)
 * AI Flow      : VLSIT RTL Generator AI Automation Flow
 * AI Flow Page : https://github.com/nguyenquanicd/APB-CSR-Generator
 * Date         : 2026-10-28
 * Description  : Control and status registers with an APB4 slave interface.
 *                Clocks: two clocks, i_clk_apb and i_clk_reg.
 *                Generated by APB-CSR-Generator v2.1; do not edit by hand.
 *                Source: sheet ASYNC_CSR of the CSR workbook.
 *                The RTL follows the VLSIT RTL Design Rule v2.
 */
`timescale 1ns/1ps

module m_vlsi_csr #(
  localparam logic [31:0] LPARA_ADDR_W = 32'd16,
  localparam logic [31:0] LPARA_DATA_W = 32'd32,
  localparam logic [31:0] LPARA_STRB_W = 32'd4,
  localparam logic [31:0] LPARA_SYNC_STAGES = 32'd2,
  localparam logic [31:0] LPARA_ABC_OFFSET = 32'h0000,
  localparam logic [31:0] LPARA_DEF_OFFSET = 32'h0004
) (
  // APB clock and reset
  input  wire                     i_clk_apb,
  input  wire                     i_rst_n_apb,

  // Register clock and reset
  input  wire                     i_clk_reg,
  input  wire                     i_rst_n_reg,

  // APB slave interface
  input  wire                     i_apb_psel,
  input  wire                     i_apb_penable,
  input  wire                     i_apb_pwrite,
  input  wire  [LPARA_ADDR_W-1:0] i_apb_paddr,
  input  wire  [LPARA_DATA_W-1:0] i_apb_pwdata,
  input  wire  [LPARA_STRB_W-1:0] i_apb_pstrb,
  input  wire  [2:0]              i_apb_pprot,
  output logic                    o_apb_pready,
  output logic                    o_apb_pslverr,
  output logic [LPARA_DATA_W-1:0] o_apb_prdata,

  // Access check control
  input  wire                     i_protect_en,
  input  wire                     i_slverr_en,

  // Register abc
  input  wire                     i_abc_start0,
  output logic                    o_abc_start1,
  output logic                    o_abc_start2,
  input  wire                     i_hw_wdata_abc_start2,
  input  wire                     i_hw_we_abc_start2,
  output logic [1:0]              o_abc_start3,
  output logic [1:0]              o_abc_start4,
  input  wire  [1:0]              i_hw_wdata_abc_start4,
  input  wire                     i_hw_we_abc_start4,

  // Register def
  output logic                    o_def_start0,
  output logic                    o_def_start1,
  input  wire                     i_hw_wdata_def_start1,
  input  wire                     i_hw_we_def_start1,
  output logic                    o_def_start2,
  input  wire                     i_hw_wdata_def_start2,
  input  wire                     i_hw_we_def_start2,
  output logic [1:0]              o_def_start3,
  input  wire  [1:0]              i_hw_wdata_def_start3,
  input  wire                     i_hw_we_def_start3,
  output logic [1:0]              o_def_start4,
  input  wire  [1:0]              i_hw_wdata_def_start4,
  input  wire                     i_hw_we_def_start4
);

  // Internal signal declarations
  logic w_apb_setup;
  logic w_apb_prot_ok;
  logic w_apb_slverr;
  logic w_apb_complete;
  logic w_apb_wr;
  logic w_apb_rd;
  logic [LPARA_ADDR_W-1:0] reg_addr;
  logic [LPARA_DATA_W-1:0] reg_wdata;
  logic reg_slverr;
  logic w_rd_en;
  logic w_wr_en;
  logic [LPARA_DATA_W-1:0] w_rdata_nxt;
  logic reg_pready;
  logic [LPARA_DATA_W-1:0] reg_rdata;
  logic w_pready_nxt;
  logic w_rd_ack;
  logic w_rd_ack_bus;
  logic reg_rd_req;
  logic w_rd_req_nxt;
  logic w_rd_ack_fall;
  logic reg_rd_ack_bus_dly;
  logic w_wr_ack;
  logic w_wr_ack_bus;
  logic reg_wr_req;
  logic w_wr_req_nxt;
  logic w_wr_ack_fall;
  logic reg_wr_ack_bus_dly;
  logic w_rd_req_reg;
  logic reg_rd_req_reg_dly;
  logic w_wr_req_reg;
  logic reg_wr_req_reg_dly;
  logic [LPARA_DATA_W-1:0] reg_rdata_bus;
  logic w_we_abc;
  logic reg_abc_start1;
  logic w_abc_start1_nxt;
  logic reg_abc_start2;
  logic w_abc_start2_nxt;
  logic [1:0] reg_abc_start3;
  logic [1:0] w_abc_start3_nxt;
  logic [1:0] reg_abc_start4;
  logic [1:0] w_abc_start4_nxt;
  logic [LPARA_DATA_W-1:0] w_abc_value;
  logic w_we_def;
  logic reg_def_start0;
  logic w_def_start0_nxt;
  logic reg_def_start1;
  logic w_def_start1_nxt;
  logic reg_def_start2;
  logic w_def_start2_nxt;
  logic [1:0] reg_def_start3;
  logic [1:0] w_def_start3_nxt;
  logic [1:0] reg_def_start4;
  logic [1:0] w_def_start4_nxt;
  logic [LPARA_DATA_W-1:0] w_def_value;

  // APB decode: the SETUP phase is PSEL high and PENABLE low and lasts one cycle per transfer.
  // A transfer is in error when the protection, the word alignment or the byte strobes fail
  // while i_slverr_en is 1.
  assign w_apb_setup    = i_apb_psel & ~i_apb_penable;
  assign w_apb_prot_ok  = i_protect_en ? ~i_apb_pprot[1] : 1'b1;
  assign w_apb_slverr   = i_slverr_en ? (~w_apb_prot_ok
                                         | (|i_apb_paddr[1:0])
                                         | (~&i_apb_pstrb & i_apb_pwrite)) : 1'b0;

  // Transfer without error, split into a write and a read.
  assign w_apb_complete = w_apb_setup & ~w_apb_slverr;
  assign w_apb_wr       = i_apb_pwrite & w_apb_complete;
  assign w_apb_rd       = ~i_apb_pwrite & w_apb_complete;

  // Address capture: holds the address of the last transfer without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_addr
    if (!i_rst_n_apb)
      reg_addr <= '0;
    else if (w_apb_complete)
      reg_addr <= i_apb_paddr;
  end

  // Write data capture: holds the data of the last write without error.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wdata
    if (!i_rst_n_apb)
      reg_wdata <= '0;
    else if (w_apb_wr)
      reg_wdata <= i_apb_pwdata;
  end

  // Error response flop: loaded in every SETUP phase while i_slverr_en is 1, and held otherwise.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_slverr
    if (!i_rst_n_apb)
      reg_slverr <= 1'b0;
    else if (w_apb_setup & i_slverr_en)
      reg_slverr <= w_apb_slverr;
  end

  // PSLVERR output follows the error response flop.
  assign o_apb_pslverr = reg_slverr;

  // Register write enables: a write enable of the captured address.
  assign w_we_abc = w_wr_en & (reg_addr == LPARA_ABC_OFFSET[LPARA_ADDR_W-1:0]);
  assign w_we_def = w_wr_en & (reg_addr == LPARA_DEF_OFFSET[LPARA_ADDR_W-1:0]);

  // Read request and acknowledge toggles cross between the APB clock and the register clock.
  // Bus clock, read: the acknowledge is synchronized into the APB clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_rd_ack_sync (
    .i_clk_dst   (i_clk_apb),
    .i_rst_n_dst (i_rst_n_apb),
    .i_d         (w_rd_ack),
    .o_q         (w_rd_ack_bus)
  );

  // Bus clock, read: the request is set by a read and cleared by the acknowledge.
  assign w_rd_req_nxt  = w_rd_ack_bus ? 1'b0 : (w_apb_rd ? 1'b1 : reg_rd_req);
  assign w_rd_ack_fall = reg_rd_ack_bus_dly & ~w_rd_ack_bus;

  // Bus clock, read: request flop and delayed acknowledge flop.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rd_req
    if (!i_rst_n_apb) begin
      reg_rd_req         <= 1'b0;
      reg_rd_ack_bus_dly <= 1'b0;
    end else begin
      reg_rd_req         <= w_rd_req_nxt;
      reg_rd_ack_bus_dly <= w_rd_ack_bus;
    end
  end

  // Bus clock, write: the acknowledge is synchronized into the APB clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_wr_ack_sync (
    .i_clk_dst   (i_clk_apb),
    .i_rst_n_dst (i_rst_n_apb),
    .i_d         (w_wr_ack),
    .o_q         (w_wr_ack_bus)
  );

  // Bus clock, write: the request is set by a write and cleared by the acknowledge.
  assign w_wr_req_nxt  = w_wr_ack_bus ? 1'b0 : (w_apb_wr ? 1'b1 : reg_wr_req);
  assign w_wr_ack_fall = reg_wr_ack_bus_dly & ~w_wr_ack_bus;

  // Bus clock, write: request flop and delayed acknowledge flop.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_wr_req
    if (!i_rst_n_apb) begin
      reg_wr_req         <= 1'b0;
      reg_wr_ack_bus_dly <= 1'b0;
    end else begin
      reg_wr_req         <= w_wr_req_nxt;
      reg_wr_ack_bus_dly <= w_wr_ack_bus;
    end
  end

  // Register clock, read: the request is synchronized into the register clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_rd_req_sync (
    .i_clk_dst   (i_clk_reg),
    .i_rst_n_dst (i_rst_n_reg),
    .i_d         (reg_rd_req),
    .o_q         (w_rd_req_reg)
  );

  // Register clock, read: a new request is a rising edge; the acknowledge is the delayed request.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rd_req_reg
    if (!i_rst_n_reg)
      reg_rd_req_reg_dly <= 1'b0;
    else
      reg_rd_req_reg_dly <= w_rd_req_reg;
  end

  // Read enable: pulse on the rising edge of the request; the acknowledge is the delayed request.
  assign w_rd_en  = ~reg_rd_req_reg_dly & w_rd_req_reg;
  assign w_rd_ack = reg_rd_req_reg_dly;

  // Register clock, write: the request is synchronized into the register clock.
  m_csr_sync #(
    .PARA_LEVELS (LPARA_SYNC_STAGES)
  ) u_wr_req_sync (
    .i_clk_dst   (i_clk_reg),
    .i_rst_n_dst (i_rst_n_reg),
    .i_d         (reg_wr_req),
    .o_q         (w_wr_req_reg)
  );

  // Register clock, write: a new request is a rising edge; the acknowledge is the delayed request.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_wr_req_reg
    if (!i_rst_n_reg)
      reg_wr_req_reg_dly <= 1'b0;
    else
      reg_wr_req_reg_dly <= w_wr_req_reg;
  end

  // Write enable: pulse on the rising edge of the request; the acknowledge is the delayed request.
  assign w_wr_en  = ~reg_wr_req_reg_dly & w_wr_req_reg;
  assign w_wr_ack = reg_wr_req_reg_dly;

  // PREADY: one pulse when a read or write is acknowledged, or after an error SETUP phase.
  assign w_pready_nxt = w_rd_ack_fall | w_wr_ack_fall | (w_apb_slverr & w_apb_setup);

  // PREADY flop: loaded with the next value, cleared by the reset.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_pready
    if (!i_rst_n_apb)
      reg_pready <= 1'b0;
    else
      reg_pready <= w_pready_nxt;
  end

  // PREADY output follows the PREADY flop.
  assign o_apb_pready = reg_pready;

  // abc_start1 next value (rw): a software write loads it, otherwise hold.
  assign w_abc_start1_nxt = (w_we_abc) ? reg_wdata[30] : reg_abc_start1;

  // abc_start2 next value (rwi): software write, then hardware write, then hold.
  assign w_abc_start2_nxt = (w_we_abc) ? reg_wdata[29]
                             : (i_hw_we_abc_start2) ? i_hw_wdata_abc_start2
                             : reg_abc_start2;

  // abc_start3 next value (rw): a software write loads it, otherwise hold.
  assign w_abc_start3_nxt = (w_we_abc) ? reg_wdata[28:27] : reg_abc_start3;

  // abc_start4 next value (rwi): software write, then hardware write, then hold.
  assign w_abc_start4_nxt = (w_we_abc) ? reg_wdata[26:25]
                             : (i_hw_we_abc_start4) ? i_hw_wdata_abc_start4
                             : reg_abc_start4;

  // Register abc: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_abc
    if (!i_rst_n_reg) begin
      reg_abc_start1 <= 1'h0;
      reg_abc_start2 <= 1'h0;
      reg_abc_start3 <= 2'h0;
      reg_abc_start4 <= 2'h0;
    end else begin
      reg_abc_start1 <= w_abc_start1_nxt;
      reg_abc_start2 <= w_abc_start2_nxt;
      reg_abc_start3 <= w_abc_start3_nxt;
      reg_abc_start4 <= w_abc_start4_nxt;
    end
  end

  // Register abc: output ports follow the flops.
  assign o_abc_start1 = reg_abc_start1;
  assign o_abc_start2 = reg_abc_start2;
  assign o_abc_start3 = reg_abc_start3;
  assign o_abc_start4 = reg_abc_start4;

  // Register abc: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_abc_value
    w_abc_value = '0;
    w_abc_value[31] = i_abc_start0;
    w_abc_value[30] = reg_abc_start1;
    w_abc_value[29] = reg_abc_start2;
    w_abc_value[28:27] = reg_abc_start3;
    w_abc_value[26:25] = reg_abc_start4;
  end

  // def_start0 next value (rw): a software write loads it, otherwise hold.
  assign w_def_start0_nxt = (w_we_def) ? reg_wdata[31] : reg_def_start0;

  // def_start1 next value (rwi): software write, then hardware write, then hold.
  assign w_def_start1_nxt = (w_we_def) ? reg_wdata[30]
                             : (i_hw_we_def_start1) ? i_hw_wdata_def_start1
                             : reg_def_start1;

  // def_start2 next value (w1c): hardware write, then software 1 clears, then hold.
  assign w_def_start2_nxt = (i_hw_we_def_start2) ? i_hw_wdata_def_start2
                             : (w_we_def) ? (~reg_wdata[29] & reg_def_start2)
                             : reg_def_start2;

  // def_start3 next value (w1c): hardware write, then software 1 clears, then hold.
  assign w_def_start3_nxt = (i_hw_we_def_start3) ? i_hw_wdata_def_start3
                             : (w_we_def) ? (~reg_wdata[28:27] & reg_def_start3)
                             : reg_def_start3;

  // def_start4 next value (rwi): software write, then hardware write, then hold.
  assign w_def_start4_nxt = (w_we_def) ? reg_wdata[26:25]
                             : (i_hw_we_def_start4) ? i_hw_wdata_def_start4
                             : reg_def_start4;

  // Register def: flops of the writable fields, reset to the field reset values.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_def
    if (!i_rst_n_reg) begin
      reg_def_start0 <= 1'h0;
      reg_def_start1 <= 1'h0;
      reg_def_start2 <= 1'h0;
      reg_def_start3 <= 2'h0;
      reg_def_start4 <= 2'h0;
    end else begin
      reg_def_start0 <= w_def_start0_nxt;
      reg_def_start1 <= w_def_start1_nxt;
      reg_def_start2 <= w_def_start2_nxt;
      reg_def_start3 <= w_def_start3_nxt;
      reg_def_start4 <= w_def_start4_nxt;
    end
  end

  // Register def: output ports follow the flops.
  assign o_def_start0 = reg_def_start0;
  assign o_def_start1 = reg_def_start1;
  assign o_def_start2 = reg_def_start2;
  assign o_def_start3 = reg_def_start3;
  assign o_def_start4 = reg_def_start4;

  // Register def: read value from the fields; reserved bits read as 0.
  always_comb begin : p_com_def_value
    w_def_value = '0;
    w_def_value[31] = reg_def_start0;
    w_def_value[30] = reg_def_start1;
    w_def_value[29] = reg_def_start2;
    w_def_value[28:27] = reg_def_start3;
    w_def_value[26:25] = reg_def_start4;
  end

  // Read data mux: value of the register at the captured address, 0 for any other address.
  always_comb begin : p_com_rdata
    w_rdata_nxt = '0;
    case (reg_addr)
      LPARA_ABC_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_abc_value;
      LPARA_DEF_OFFSET[LPARA_ADDR_W-1:0]: w_rdata_nxt = w_def_value;
      default: w_rdata_nxt = '0;
    endcase
  end

  // Read data snapshot in the register clock domain, loaded by the read enable of that domain.
  always_ff @(posedge i_clk_reg, negedge i_rst_n_reg) begin : p_ff_rdata
    if (!i_rst_n_reg)
      reg_rdata <= '0;
    else if (w_rd_en)
      reg_rdata <= w_rdata_nxt;
  end

  // Read data resynchronized to the APB clock: reg_rdata is stable when the acknowledge
  // pulse arrives, so that pulse samples it without a bit synchronizer.
  always_ff @(posedge i_clk_apb, negedge i_rst_n_apb) begin : p_ff_rdata_bus
    if (!i_rst_n_apb)
      reg_rdata_bus <= '0;
    else if (w_rd_ack_fall)
      reg_rdata_bus <= reg_rdata;
  end

  // PRDATA output follows the read data flop of the APB clock.
  assign o_apb_prdata = reg_rdata_bus;

endmodule
